import{_ as o}from"./chunks/architecture-zh-CN.EQpNaQPQ.js";import{_ as r,o as a,c as t,a2 as c}from"./chunks/framework.BWuWLRhz.js";const S=JSON.parse('{"title":"系統架構設計","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/dev-guide/architecture.md","filePath":"zh-HK/dev-guide/architecture.md","lastUpdated":1790965225000}'),d={name:"zh-HK/dev-guide/architecture.md"};function i(l,e,s,n,h,p){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="系統架構設計" tabindex="-1">系統架構設計 <a class="header-anchor" href="#系統架構設計" aria-label="Permalink to &quot;系統架構設計&quot;">​</a></h1><p>Lertaro 採用先進的多程序隔離架構與模組化分層設計，確保在實現系統級毫秒檢索與全方位視窗整合的同時，兼顧最高級別的運行安全與穩定性。</p><p><img src="'+o+'" alt="Lertaro 架構圖"></p><h2 id="_1-三程序隔離模型" tabindex="-1">1. 三程序隔離模型 <a class="header-anchor" href="#_1-三程序隔離模型" aria-label="Permalink to &quot;1. 三程序隔離模型&quot;">​</a></h2><p>為了徹底規避單一元件異常導致整個系統當機，並將 Windows 特權限制在最小範圍內，Lertaro 的執行階段被明確劃分為三個獨立的程序：</p><h3 id="_1-後台索引服務-lertaro-service" tabindex="-1">1. 後台索引服務（<code>Lertaro.Service</code>） <a class="header-anchor" href="#_1-後台索引服務-lertaro-service" aria-label="Permalink to &quot;1. 後台索引服務（`Lertaro.Service`）&quot;">​</a></h3><ul><li><strong>運行身份</strong>：以 Windows 系統級 <code>LocalSystem</code> 身份常駐運行的 Windows 服務。</li><li><strong>職責範圍</strong>：承擔全盤檔案索引與增量監聽的核心重任。直接讀取 NTFS / ReFS 磁碟底層的 USN 變更記錄檔與 $MFT 主檔案表；即時監聽 FAT32 / exFAT 磁碟變更；定時抓取並快取 SMB / NAS 網路共用。</li><li><strong>安全與效能考量</strong>：運行在 SYSTEM 級別使服務無需彈出任何 UAC 提權快顯視窗即可直接讀取原始磁碟卷的中繼資料；同時透過高效能具名管道向用戶態 App 返回檢索結果，徹底避免了讓前景 UI 程序持有不必要的全域高權限。</li></ul><h3 id="_2-用戶互動主程式-lertaro-app" tabindex="-1">2. 用戶互動主程式（<code>Lertaro.App</code>） <a class="header-anchor" href="#_2-用戶互動主程式-lertaro-app" aria-label="Permalink to &quot;2. 用戶互動主程式（`Lertaro.App`）&quot;">​</a></h3><ul><li><strong>運行身份</strong>：標準 Windows 用戶態、Session 隔離的 WPF 前景桌面應用程式。</li><li><strong>職責範圍</strong>：承載快速搜尋置中浮動視窗、完整主搜尋視窗、設定中心、全域快速鍵分發、動作選單（<code>Ctrl+O</code>）以及 QuickLook 檔案即時預覽介面。</li><li><strong>IPC 橋樑與 CLI 託管</strong>：透過雙向具名管道 <code>LertaroPipe</code> 與後台 Service 溝通（<code>Core.Services.Search.SearchService</code> 是 App 端的用戶端）。同時，App 自身還託管了一條面向當前用戶的專屬具名管道服務（<code>AppSearchPipeService</code>），使外部伴隨工具（如 <code>lff</code> 命令列工具）能直接複用 App 已經構建好的記憶體別名表、外掛模組提供者與網路磁碟快取，無需重複初始化。</li></ul><h3 id="_3-全域鍵盤掛鉤與視窗適配程序-lertaro-service-hook" tabindex="-1">3. 全域鍵盤掛鉤與視窗適配程序（<code>Lertaro.Service --hook</code>） <a class="header-anchor" href="#_3-全域鍵盤掛鉤與視窗適配程序-lertaro-service-hook" aria-label="Permalink to &quot;3. 全域鍵盤掛鉤與視窗適配程序（`Lertaro.Service --hook`）&quot;">​</a></h3><ul><li><strong>運行身份</strong>：由後台服務拉起的獨立輔助程序。只有在登入帳號確為真正的管理員時才會<strong>以提權方式啟動</strong>；否則它沿用使用者自己的權杖運行，因此下述的突破只在該台機器上可用。</li><li><strong>職責範圍</strong>：託管低階全域鍵盤掛鉤（Low-Level Keyboard Hook）與滑鼠全域監聽。</li><li><strong>UIPI 權限突破與崩潰隔離</strong>：在 Windows 安全體系中，低完整性級別的用戶態程序無法向以管理員身份運行的高權限視窗發送視窗訊息或模擬輸入（UIPI 隔離）。透過在該 Hook 程序中運行視窗整合適配器（<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a>），只要 Hook 是以提權方式啟動，Lertaro 便能讀取並驅動由管理員身份啟動的檔案總管、Total Commander 或第三方對話方塊。同時，即使底層掛鉤因第三方遊戲的反作弊模組產生異常，也不會影響主 App 程序的正常運行。</li></ul><h2 id="_2-共用核心層-shared-core-library" tabindex="-1">2. 共用核心層（Shared Core Library） <a class="header-anchor" href="#_2-共用核心層-shared-core-library" aria-label="Permalink to &quot;2. 共用核心層（Shared Core Library）&quot;">​</a></h2><p><code>Lertaro.Core</code> 是被 Service、App 和 Hook 程序同時引用的基礎類別庫，主要包含以下關鍵模組：</p><ul><li><strong>自研 fzf 模糊比對引擎（<code>Core/SearchIndex/Fzf/*</code>）</strong>：高效復刻並最佳化了知名 <code>fzf</code> 演算法的跳躍字元模糊比對、子字串分段與字元級反白計算，配合 <code>SearchQueryParser</code> 實現磁碟機定向與路徑模式切分。</li><li><strong>欄式記憶體索引（<code>Core/IndexV2/*</code>）</strong>：採用記憶體對應欄式快照（Columnar Snapshot）與記憶體增量覆蓋層（Delta Overlay），實現億級檔案項目的亞毫秒級檢索。</li><li><strong>二進位 IPC 通訊契約</strong>：定義了 <code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等標準二進位資料通訊協定，確保多程序間零拷貝高效序列化。</li><li><strong>統一多程序記錄系統（<code>Logger</code>）</strong>：分別輸出至 <code>service.log</code>、<code>app.log</code> 與 <code>hook.log</code>，並由 App 的設定中心記錄檢視器統一代理讀取與呈現。</li></ul><h2 id="_3-外掛模組系統在架構中的定位" tabindex="-1">3. 外掛模組系統在架構中的定位 <a class="header-anchor" href="#_3-外掛模組系統在架構中的定位" aria-label="Permalink to &quot;3. 外掛模組系統在架構中的定位&quot;">​</a></h2><p>所有第三方及內建外掛模組均基於 <code>Lertaro.PluginSdk</code> 構建，由 <code>Lertaro.App</code> 程序在啟動時自動反射掃描並載入：</p><ul><li><strong>零特權直接存取</strong>：外掛模組自己的程式碼與載入它的程序同進程運行——通常是 App，但另有兩種類型的元件會被 Service 一併載入，請見下一點。外掛模組不會自行跨越程序邊界，因此需要自訂目錄索引時，應透過 <code>DirectoryIndexerService</code> 委派工作，而不是自己去走訪磁碟。</li><li><strong>選擇性雙重載入</strong>：搜尋來源、動作與介面擴充元件僅在 App 程序中運行。另有三項會被載入其他程序：視窗與檔案對話方塊適配器（<code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code>）會進入 Hook 程序以處理跨完整性級別的視窗自動化；而 <code>IAliasProvider</code> 與 <code>ITranslationProvider</code> 也會由 <strong>Service</strong> 載入（<code>ServicePluginLoader</code>），因為索引器要建立別名資料列，需要與 UI 顯示相同的轉寫與命名。</li></ul>',17)])])}const _=r(d,[["render",i]]);export{S as __pageData,_ as default};
